"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Now with JWT authentication: users own their tasks.
"""

from flask import Flask, request, jsonify
from functools import wraps
import sqlite3
import os

import jwt as pyjwt
from werkzeug.security import generate_password_hash, check_password_hash

from tasks import send_notification_email
from repositories import UserRepository, TaskRepository

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")
SECRET_KEY = os.environ.get("SECRET_KEY", "dev-secret-key-change-me-in-production-0123456789")
JWT_ALGORITHM = "HS256"


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


# ── Repositories ──────────────────────────────────────────────

user_repository = UserRepository(get_db)
task_repository = TaskRepository(get_db)


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL,"
            "  email TEXT"
            ")"
        )
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL,"
            "  owner_id INTEGER REFERENCES users(id)"
            ")"
        )
        conn.commit()
    migrate()


def migrate():
    """Add missing columns (owner_id, email) without breaking existing data."""
    with get_db() as conn:
        task_columns = {row["name"] for row in conn.execute("PRAGMA table_info(tasks)")}
        if "owner_id" not in task_columns:
            conn.execute(
                "ALTER TABLE tasks ADD COLUMN owner_id INTEGER REFERENCES users(id)"
            )
        user_columns = {row["name"] for row in conn.execute("PRAGMA table_info(users)")}
        if "email" not in user_columns:
            conn.execute("ALTER TABLE users ADD COLUMN email TEXT")
        conn.commit()


# ── Auth helpers ──────────────────────────────────────────────

def make_token(user_id: int, username: str) -> str:
    payload = {"sub": str(user_id), "username": username}
    return pyjwt.encode(payload, SECRET_KEY, algorithm=JWT_ALGORITHM)


def current_user() -> dict | None:
    auth_header = request.headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        return None
    token = auth_header[len("Bearer "):].strip()
    try:
        payload = pyjwt.decode(token, SECRET_KEY, algorithms=[JWT_ALGORITHM])
    except pyjwt.PyJWTError:
        return None
    user_id = payload.get("sub")
    if user_id is None:
        return None
    return user_repository.find_by_id(int(user_id))


def require_auth(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        user = current_user()
        if user is None:
            return jsonify({"error": "unauthorized"}), 401
        return fn(user, *args, **kwargs)

    return wrapper


# ── Auth routes ───────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    email = (data.get("email") or "").strip() or None
    if not username or not password:
        return jsonify({"error": "username and password are required"}), 400
    if user_repository.find_by_username(username) is not None:
        return jsonify({"error": "username already exists"}), 409
    user = user_repository.create(username, generate_password_hash(password), email)
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    user = user_repository.find_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid credentials"}), 401
    token = make_token(user["id"], user["username"])
    return jsonify({"token": token})


# ── Task routes ───────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks(user):
    return jsonify(task_repository.find_all(user["id"]))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task(user):
    data = request.get_json(silent=True) or {}
    title = data.get("title", "").strip()
    if not title:
        return jsonify({"error": "title is required"}), 400
    task = task_repository.create(title, user["id"])
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(user, task_id: int):
    task = task_repository.find_by_id_and_owner(task_id, user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(user, task_id: int):
    data = request.get_json(silent=True) or {}
    previous = task_repository.find_by_id_and_owner(task_id, user["id"])
    task = task_repository.update(
        task_id,
        user["id"],
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if (
        data.get("status") == "completed"
        and (previous is None or previous.get("status") != "completed")
    ):
        user_email = user.get("email") or f"{user['username']}@example.com"
        try:
            send_notification_email.delay(user_email, task["title"])
        except Exception:
            app.logger.exception("Failed to enqueue notification email")
    return jsonify(task)


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

"""
Data access layer — Repository pattern.

All SQLite queries live here. Route handlers in ``app.py`` only interact
with these repository objects, never with SQLite directly.
"""

from abc import ABC, abstractmethod
from datetime import datetime
import sqlite3


class BaseRepository(ABC):
    """Abstract base class providing common CRUD operations."""

    table: str = ""

    def __init__(self, get_db):
        self._get_db = get_db

    def _connect(self):
        return self._get_db()

    @abstractmethod
    def create(self, **fields) -> dict | None:
        """Insert a new record and return it, or ``None`` on conflict."""

    def find_by_id(self, entity_id) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(
                f"SELECT * FROM {self.table} WHERE id = ?", (entity_id,)
            ).fetchone()
            return dict(row) if row else None

    def find_all(self) -> list[dict]:
        with self._connect() as conn:
            rows = conn.execute(f"SELECT * FROM {self.table}").fetchall()
            return [dict(r) for r in rows]

    def update(self, entity_id, **fields) -> dict | None:
        if not fields:
            return self.find_by_id(entity_id)
        assignments = ", ".join(f"{column} = ?" for column in fields)
        with self._connect() as conn:
            conn.execute(
                f"UPDATE {self.table} SET {assignments} WHERE id = ?",
                (*fields.values(), entity_id),
            )
            conn.commit()
        return self.find_by_id(entity_id)

    def delete(self, entity_id) -> bool:
        with self._connect() as conn:
            cursor = conn.execute(
                f"DELETE FROM {self.table} WHERE id = ?", (entity_id,)
            )
            conn.commit()
            return cursor.rowcount > 0


class UserRepository(BaseRepository):
    table = "users"

    def create(self, username: str, password_hash: str, email: str | None = None) -> dict | None:
        with self._connect() as conn:
            try:
                cursor = conn.execute(
                    "INSERT INTO users (username, password_hash, email) VALUES (?, ?, ?)",
                    (username, password_hash, email),
                )
                conn.commit()
                return {"id": cursor.lastrowid, "username": username, "email": email}
            except sqlite3.IntegrityError:
                return None

    def find_by_username(self, username: str) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM users WHERE username = ?", (username,)
            ).fetchone()
            return dict(row) if row else None


class TaskRepository(BaseRepository):
    table = "tasks"

    def create(self, title: str, owner_id: int) -> dict:
        now = datetime.utcnow().isoformat()
        with self._connect() as conn:
            cursor = conn.execute(
                "INSERT INTO tasks (title, status, created_at, owner_id)"
                " VALUES (?, 'pending', ?, ?)",
                (title, now, owner_id),
            )
            conn.commit()
            return {
                "id": cursor.lastrowid,
                "title": title,
                "status": "pending",
                "created_at": now,
                "owner_id": owner_id,
            }

    def find_all(self, owner_id: int) -> list[dict]:
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC",
                (owner_id,),
            ).fetchall()
            return [dict(r) for r in rows]

    def find_by_id_and_owner(self, task_id: int, owner_id: int) -> dict | None:
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM tasks WHERE id = ? AND owner_id = ?",
                (task_id, owner_id),
            ).fetchone()
            return dict(row) if row else None

    def update(
        self,
        task_id: int,
        owner_id: int,
        title: str | None = None,
        status: str | None = None,
    ) -> dict | None:
        task = self.find_by_id_and_owner(task_id, owner_id)
        if task is None:
            return None
        with self._connect() as conn:
            updates = []
            params = []
            if title is not None:
                updates.append("title = ?")
                params.append(title)
            if status is not None:
                updates.append("status = ?")
                params.append(status)
            if updates:
                params.append(task_id)
                params.append(owner_id)
                conn.execute(
                    f"UPDATE tasks SET {', '.join(updates)} WHERE id = ? AND owner_id = ?",
                    params,
                )
                conn.commit()
        return self.find_by_id_and_owner(task_id, owner_id)

